local function genCoords()local function rnd()local m=math.random(1,4)local s=math.random()<0.35 and-1 or 1 return s*math.random(1,10^m-1)end return string.format("%d %d %d",rnd(),rnd(),rnd())end
local function An(p,f,t,d)if not p or not p.Parent then return end task.spawn(function()for i=1,20 do if not p.Parent then return end local a=i/20 local c=f:Lerp(t,a)pcall(function()p.Color=c local inner=p:FindFirstChild("Inner")if inner then inner.Color=c end local pl=p:FindFirstChildOfClass("PointLight")if pl then pl.Color=c end end)task.wait(d/20)end end)end
local function getLabel()if PendingName then return"▼ "..PendingName.." ▼"end if PCN=="green"then return LG("greenPortal")end if PCN=="yellow"then return LG("yellowPortal")end if PCN=="red"then return LG("redPortal")end if PCN=="orange"then return LG("orangePortal")end if PCN=="blue"then return LG("bluePortal")end if PCN=="purple"then return LG("purplePortal")end if PCN=="pink"then return LG("pinkPortal")end if PCN=="white"then return LG("whitePortal")end if PCN=="black"then return LG("blackPortal")end if PCN=="rainbow"then return LG("rainbowPortal")end return LG("greenPortal")end
local function trailTeleport(newPos)local r=hr()if not r then return end local startPos=r.Position local dist=(newPos-startPos).Magnitude local steps=math.max(1,math.floor(dist/2.5))local baseCol=PC for i=1,steps do local t=i/steps local p=startPos+(newPos-startPos)*t+Vector3.new(0,math.random(-1,1),0)local tile=Instance.new("Part")tile.Size=Vector3.new(1.5,0.2,1.5)tile.Position=p tile.Anchored=true tile.CanCollide=false tile.CanQuery=false tile.Material=Enum.Material.Neon if PCN=="rainbow"then tile.Color=Color3.fromHSV((tick()+i*0.1)%1,1,1)else tile.Color=baseCol end tile.Transparency=0.2 tile.Parent=W table.insert(WO2,tile)task.spawn(function()T:Create(tile,TweenInfo.new(2),{Size=Vector3.new(0.1,0.05,0.1),Transparency=1}):Play()task.wait(2)if tile.Parent then tile:Destroy()end end)end r.CFrame=CFrame.new(newPos)end
local function killNearbyNPCs(ball)local conn conn=R.Heartbeat:Connect(function()if not ball.Parent then if conn then conn:Disconnect()end return end for _,obj in ipairs(W:GetDescendants())do if obj:IsA("Model")and(obj.Name=="NPC"or obj.Name=="Alien"or obj.Name=="Demon"or obj.Name=="Angel")then local pr=obj.PrimaryPart if pr and(pr.Position-ball.Position).Magnitude<5 then if not obj:GetAttribute("dead")then obj:SetAttribute("dead",true)local rw=allWorlds[math.random(1,#allWorlds)]showNpcWorldText(rw)killCount=killCount+1 obj:Destroy()end end end end end)task.delay(3,function()if conn then conn:Disconnect()end end)end
local function createPortal(special)local root=hr()if not root then return nil end local look=root.CFrame.LookVector if look.Magnitude<0.01 then look=Vector3.new(0,0,-1)end local startPos=root.Position+look*5 local endPos=root.Position+look*35 local baseCol=special and Color3.fromRGB(255,220,40)or PC local ball=Instance.new("Part")ball.Shape=Enum.PartType.Ball ball.Size=Vector3.new(3,3,3)ball.Position=startPos ball.Anchored=true ball.CanCollide=false ball.CanQuery=false ball.Material=Enum.Material.Neon ball.Color=baseCol ball.Transparency=0.2 ball.Parent=W local pl=Instance.new("PointLight")pl.Range=25 pl.Brightness=5 pl.Color=baseCol pl.Parent=ball if Progress.ufoQuestDone then killNearbyNPCs(ball)end T:Create(ball,TweenInfo.new(1.5,Enum.EasingStyle.Linear),{Position=endPos}):Play()task.wait(1.5)if not ball.Parent then return nil end ball.Shape=Enum.PartType.Cylinder local cf=CFrame.new(endPos,endPos+look)*CFrame.Angles(0,math.rad(90),0)ball.CFrame=cf T:Create(ball,TweenInfo.new(0.5,Enum.EasingStyle.Back),{Size=Vector3.new(1,10,10)}):Play()task.wait(0.5)if not ball.Parent then return nil end local p=ball p.Name="Portal"p.Transparency=0.15 p.CanTouch=false local inner=Instance.new("Part")inner.Name="Inner"inner.Shape=Enum.PartType.Cylinder inner.Size=Vector3.new(0.8,6,6)inner.CFrame=cf inner.Anchored=true inner.CanCollide=false inner.CanTouch=false inner.CanQuery=false inner.Material=Enum.Material.Neon inner.Color=baseCol inner.Transparency=0.4 inner.Parent=p local pl2=Instance.new("PointLight")pl2.Range=20 pl2.Brightness=3 pl2.Shadows=false pl2.Color=baseCol pl2.Parent=p local bb=Instance.new("BillboardGui")bb.Size=UDim2.new(0,220,0,50)bb.StudsOffset=Vector3.new(0,8,0)bb.AlwaysOnTop=true bb.Parent=p local lbl=Instance.new("TextLabel")lbl.Size=UDim2.new(1,0,1,0)lbl.BackgroundTransparency=1 if special then lbl.Text=LG("specialPortal")else lbl.Text=getLabel()end lbl.TextColor3=baseCol lbl.Font=Enum.Font.GothamBold lbl.TextSize=18 lbl.TextStrokeTransparency=0.3 lbl.Parent=bb local snd=Instance.new("Sound")snd.SoundId="rbxassetid://9118823101"snd.Looped=true snd.Volume=0.4 snd.Parent=p pcall(function()snd:Play()end)local conn conn=R.Heartbeat:Connect(function(dt)if not p.Parent then if conn then conn:Disconnect()end return end pcall(function()p.CFrame=p.CFrame*CFrame.Angles(math.rad(dt*30),0,0)inner.CFrame=p.CFrame local pulse=1+math.sin(tick()*4)*0.08 p.Size=Vector3.new(1,10*pulse,10*pulse)end)end)table.insert(WL2,conn)if PCN=="rainbow"and not special then if portalRainbowConn then portalRainbowConn:Disconnect()end portalHue=0 portalRainbowConn=R.Heartbeat:Connect(function(dt)if not p.Parent then if portalRainbowConn then portalRainbowConn:Disconnect()portalRainbowConn=nil end return end portalHue=(portalHue+dt*0.5)%1 local c=Color3.fromHSV(portalHue,1,1)pcall(function()p.Color=c inner.Color=c pl2.Color=c lbl.TextColor3=c end)end)end return p end
