local function handleCommand(text)text=text:gsub("^%s+",""):gsub("%s+$","")if text==""then return end local lower=text:lower()local lang=lower:match("^lang%s+(%w+)$")if lang then if lang=="ru"then Lang="ru"elseif lang=="en"then Lang="en"end TT(LG("langSet"),Color3.fromRGB(120,255,180))return end if lower=="noclip on"then noclipOn()return end if lower=="noclip off"then noclipOff()return end if lower=="speed on"then speedOn()return end if lower=="speed off"then speedOff()return end if lower=="jump on"then jumpOn()return end if lower=="jump off"then jumpOff()return end local x,y,z=lower:match("^(-?%d+)%s+(-?%d+)%s+(-?%d+)$")if x and y and z then local r=hr()if r then local rx=tonumber(x)+(math.random()<0.5 and-1 or 1)*math.random(100,1000000)local rz=tonumber(z)+(math.random()<0.5 and-1 or 1)*math.random(100,1000000)local ry=tonumber(y)+math.random(0,50)trailTeleport(Vector3.new(rx,ry,rz))B("ТП",Color3.fromRGB(120,255,180))end return end if lower=="random"then local r=hr()if r then local a=math.random()*math.pi*2 local d=math.random(50,200)local nx=r.Position.X+math.cos(a)*d local nz=r.Position.Z+math.sin(a)*d trailTeleport(Vector3.new(nx,gr(nx,nz),nz))end return end local pn=lower:match("^player%s+(.+)$")if pn then local t=findPlayer(pn)if t and t.Character then local tr=t.Character:FindFirstChild("HumanoidRootPart")if tr then trailTeleport(tr.Position+Vector3.new(0,3,0))B("ТП",Color3.fromRGB(120,255,180))end else TT("Нет игрока",Color3.fromRGB(255,100,100))end return end local nn=lower:match("^npc%s+(.+)$")if nn then local part=findByName(nn)if part then trailTeleport(part.Position+Vector3.new(0,3,0))B("ТП",Color3.fromRGB(120,255,180))else TT("Нет NPC",Color3.fromRGB(255,100,100))end return end local inm=lower:match("^item%s+(.+)$")if inm then local part=findByName(inm)if part then trailTeleport(part.Position+Vector3.new(0,3,0))B("ТП",Color3.fromRGB(120,255,180))else TT("Нет предмета",Color3.fromRGB(255,100,100))end return end local gal=lower:match("^galactic%s+([a-z